import React from "react";

const Result = ({ style, occasion }) => {
  const outfitSuggestions = {
    Classic: {
      Work: "tailored blazer, structured vest, wide-leg trousers, and minimal accessories",
      Party: "Midi dress, subtle jewelry",
      Casual: "White tee + jeans, loafers",
      Vacation: "Linen pants + tank, straw accessories",
    },
    Boho: {
      Work: "Flowy blouse + wide-leg pants",
      Party: "Embroidered kurta set, tribal jewelry",
      Casual: "Maxi dress, denim jacket, sandals",
      Vacation: "Flared skirt, crop top, woven tote",
    },
    Chic: {
      Work: "Monochrome suit, statement heels",
      Party: "Co-ord set, sleek bun, bold lip",
      Casual: "Pleated skirt, structured top, clutch",
      Vacation: "Matching sets, gold jewelry, sunglasses",
    },
    Streetwear: {
      Work: "Oversized blazer + joggers, edgy sneakers",
      Party: "Graphic tee, mini skirt, platforms",
      Casual: "Cargo pants, oversized tee, cap",
      Vacation: "Hoodie dress, crossbody bag, slides",
    },
  };

  const outfit = style && occasion ? outfitSuggestions[style]?.[occasion] : "";

  return (
    <div style={{ padding: "20px", maxWidth: "600px", margin: "0 auto" }}>
      <h2>🎉 Your Outfit Recommendation</h2>

      {style && occasion ? (
        <>
          <p>
            For <strong>{occasion}</strong> in <strong>{style}</strong> style:
          </p>
          <p style={{ fontSize: "18px", background: "#f0f0f0", padding: "10px", borderRadius: "6px" }}>
            {outfit}
          </p>

          {/* Conditional Image Embed */}
          {style === "Classic" && occasion === "Work" && (
  <div style={{ marginTop: "20px" }}>
    <h3>🔍 Outfit Inspiration:</h3>
    <iframe
      src="https://assets.pinterest.com/ext/embed.html?id=880453795908804625"
      height="714"
      width="345"
      frameBorder="0"
      scrolling="no"
      title="Classic Work Outfit"
    ></iframe>
  </div>
)}

        </>
      ) : (
        <p>Please complete the quiz to see your outfit!</p>
      )}
    </div>
  );
};

export default Result;
